-- ORM-style application CRUD for an order management schema (Oracle 19c)
SELECT * FROM customers WHERE customer_id = :id;
SELECT c.customer_id, c.first_name, c.last_name, c.email FROM customers c WHERE c.status = 'ACTIVE' AND c.created_at > SYSDATE - 30 ORDER BY c.created_at DESC;
SELECT "ID", "NAME", "CreatedAt" FROM "AppUsers" WHERE "ID" = :1;
INSERT INTO customers (customer_id, first_name, last_name, email, created_at) VALUES (customers_seq.NEXTVAL, :first_name, :last_name, :email, SYSDATE);
INSERT INTO orders (order_id, customer_id, order_date, status, total_amount) VALUES (orders_seq.NEXTVAL, :cust_id, SYSTIMESTAMP, 'NEW', 0);
INSERT INTO order_items (item_id, order_id, product_id, quantity, unit_price) VALUES (order_items_seq.NEXTVAL, :order_id, :product_id, :qty, :price);
INSERT INTO audit_log (id, action, performed_by, performed_at) SELECT audit_seq.NEXTVAL, 'PURGE', USER, SYSTIMESTAMP FROM dual;
INSERT INTO customers_archive SELECT * FROM customers WHERE status = 'CLOSED';
UPDATE customers SET email = :email, updated_at = SYSDATE WHERE customer_id = :id;
UPDATE orders SET status = 'SHIPPED', shipped_at = SYSTIMESTAMP WHERE order_id = :order_id AND status = 'PAID';
UPDATE order_items oi SET unit_price = (SELECT p.list_price FROM products p WHERE p.product_id = oi.product_id) WHERE EXISTS (SELECT 1 FROM products p WHERE p.product_id = oi.product_id);
UPDATE employees SET salary = salary * 1.05 WHERE department_id = 50 AND ROWNUM <= 100;
DELETE FROM sessions WHERE expires_at < SYSTIMESTAMP;
DELETE FROM order_items WHERE order_id IN (SELECT order_id FROM orders WHERE status = 'CANCELLED');
DELETE FROM temp_staging;
SELECT order_id, status FROM orders WHERE order_id = :id FOR UPDATE;
SELECT order_id FROM orders WHERE status = 'NEW' ORDER BY order_date FOR UPDATE SKIP LOCKED;
SELECT account_id, balance FROM accounts WHERE account_id = :id FOR UPDATE NOWAIT;
SELECT * FROM products WHERE ROWNUM <= 10;
SELECT * FROM (SELECT p.*, ROWNUM rn FROM (SELECT * FROM products ORDER BY product_name) p WHERE ROWNUM <= 40) WHERE rn > 20;
SELECT * FROM products ORDER BY product_name OFFSET 20 ROWS FETCH NEXT 20 ROWS ONLY;
SELECT * FROM products ORDER BY list_price DESC FETCH FIRST 10 ROWS ONLY;
SELECT * FROM products ORDER BY list_price DESC FETCH FIRST 5 PERCENT ROWS ONLY;
SELECT * FROM products ORDER BY list_price DESC FETCH FIRST 3 ROWS WITH TIES;
INSERT INTO orders (order_id, customer_id, status) VALUES (orders_seq.NEXTVAL, :cid, 'NEW') RETURNING order_id INTO :new_id;
UPDATE accounts SET balance = balance - :amt WHERE account_id = :id RETURNING balance INTO :new_balance;
SELECT orders_seq.CURRVAL FROM dual;
SELECT customer_id, NVL(phone, 'N/A') AS phone, NVL2(fax, 'HAS_FAX', 'NO_FAX') AS fax_flag FROM customers;
SELECT order_id, DECODE(status, 'N', 'New', 'P', 'Paid', 'S', 'Shipped', 'Unknown') AS status_text FROM orders;
SELECT COALESCE(mobile, phone, email) AS contact FROM customers;
SELECT customer_id FROM customers WHERE UPPER(email) LIKE UPPER(:pattern) ESCAPE '\';
SELECT * FROM customers WHERE REGEXP_LIKE(email, '^[a-z0-9._%-]+@[a-z0-9.-]+\.[a-z]{2,4}$', 'i');
SELECT * FROM orders WHERE order_date BETWEEN TO_DATE('2024-01-01', 'YYYY-MM-DD') AND TO_DATE('2024-12-31 23:59:59', 'YYYY-MM-DD HH24:MI:SS');
SELECT * FROM orders WHERE order_date >= DATE '2024-01-01' AND order_date < DATE '2025-01-01';
SELECT * FROM events WHERE created_at > TIMESTAMP '2024-06-01 00:00:00';
SELECT TRUNC(SYSDATE) AS today, TRUNC(SYSDATE, 'MM') AS month_start, ADD_MONTHS(SYSDATE, 3) AS plus3, LAST_DAY(SYSDATE) AS eom FROM dual;
SELECT SYSDATE + INTERVAL '7' DAY FROM dual;
SELECT TO_CHAR(order_date, 'YYYY-MM-DD HH24:MI:SS') FROM orders;
